import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Stage 5 · 记忆与进化","description":"Hearth Stage 5 开发模块：Memory Core、记忆浏览器、冲突与遗忘、轨迹挖掘、技能候选、评估、晋升与回滚。","frontmatter":{"title":"Stage 5 · 记忆与进化","description":"Hearth Stage 5 开发模块：Memory Core、记忆浏览器、冲突与遗忘、轨迹挖掘、技能候选、评估、晋升与回滚。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-5.md","filePath":"delivery/stage-5.md","lastUpdated":null}'),o={name:"delivery/stage-5.md"};function i(d,t,n,s,h,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<p class="eyebrow">MODULE 5 / 7</p><h1 id="stage-5-·-记忆与进化" tabindex="-1">Stage 5 · 记忆与进化 <a class="header-anchor" href="#stage-5-·-记忆与进化" aria-label="Permalink to &quot;Stage 5 · 记忆与进化&quot;">​</a></h1><p class="lead">让 Hearth 积累个人上下文并改进方法，但记忆污染和技能漂移不能变成不可解释的黑箱。顺序是先让记忆可纠正，再可遗忘，再让技能可评估，最后才允许晋升。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>任务来源、权限和审批边界稳定，敏感信息已被正确分级。</li><li>记忆写入、检索和注入不会绕过 Mandate 或扩大权限。</li><li>已有代表性任务、成功/失败样本和可重复的评估集。</li></ul><h2 id="开发步骤" tabindex="-1">开发步骤 <a class="header-anchor" href="#开发步骤" aria-label="Permalink to &quot;开发步骤&quot;">​</a></h2><ol><li><strong>交付 Memory Core。</strong> 落地五类记忆、来源、敏感度、时间、置信度、作用域和检索预算；提供记忆浏览器与“为什么召回”视图。</li><li><strong>处理冲突与遗忘。</strong> 实现写入冲突、纠正、删除、tombstone、遗忘传播、导出和数据迁移。</li><li><strong>挖掘轨迹与技能候选。</strong> 从真实轨迹中提取可复用方法，形成候选、版本、权限和评估集，不允许自动扩大权限。</li><li><strong>建立评估与晋升门。</strong> 运行 Shadow、Canary、Promote、Rollback；使用对照评估、安全回归和人工复核。</li><li><strong>完成首个晋升案例。</strong> 至少让一个技能走完候选、评估、试点、晋升和回滚的完整链路，并向用户解释原因。</li><li><strong>完成 Stage 5 发布。</strong> 评估记忆准确率、注入质量、遗忘、导出、技能收益、权限和安全回归。</li></ol><h2 id="增量拆分" tabindex="-1">增量拆分 <a class="header-anchor" href="#增量拆分" aria-label="Permalink to &quot;增量拆分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>增量</th><th>用户可见结果</th><th>完成证据</th></tr></thead><tbody><tr><td>D5.1 Memory Core 与记忆浏览器</td><td>用户能查看、理解和纠正被使用的记忆</td><td>五类记忆、来源、预算、召回解释</td></tr><tr><td>D5.2 记忆冲突、遗忘与导出</td><td>错误记忆可纠正，遗忘可传播，数据可导出</td><td>tombstone、传播、导出、迁移测试</td></tr><tr><td>D5.3 轨迹、技能候选与评估集</td><td>系统能从任务中提出可复用方法</td><td>轨迹挖掘、候选、版本、评估样本</td></tr><tr><td>D5.4 Evolution 晋升门与 Stage 5 发布</td><td>新方法有对照证据，并可回滚</td><td>Shadow、Canary、Promote、Rollback 案例</td></tr></tbody></table><h2 id="退出验收" tabindex="-1">退出验收 <a class="header-anchor" href="#退出验收" aria-label="Permalink to &quot;退出验收&quot;">​</a></h2><ul><li>[ ] 记忆可解释、可纠正、可遗忘、可导出，遗忘能够传播。</li><li>[ ] 记忆注入准确率达标，敏感信息不进入不允许的上下文。</li><li>[ ] 技能晋升有对照评估，权限不会因自进化扩大。</li><li>[ ] 至少一个技能完成晋升与回滚演示。</li><li>[ ] 用户能理解系统为什么召回某段记忆或采用某个新方法。</li></ul><h2 id="本模块不做" tabindex="-1">本模块不做 <a class="header-anchor" href="#本模块不做" aria-label="Permalink to &quot;本模块不做&quot;">​</a></h2><ul><li>不做没有来源、没有评估、没有回滚的自进化。</li><li>不让记忆投毒改变权限、审批策略或系统事实。</li><li>不用“模型觉得有用”替代可重复评估。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>进入 <a href="/hearth-os/delivery/stage-6.html">Stage 6 · 多设备与长期运行</a>，把单机产品扩展为长期驻留、可迁移的 Personal Agent OS。</p>',15)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
